        return (a, 1, 0)
    g, x1, y1 = egcd(b, a % b)
    return (g, y1, x1 - (a // b) * y1)

def modinv(a, m):
    g, x, y = egcd(a, m)
    if g != 1:
        return None
    return x % m

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a // gcd(a, b) * b

def parse_cycles(sigma, R):
    visited = [False] * (R + 1)
    cycles = []
    for i in range(1, R + 1):
        if not visited[i]:
            cyc = []
            j = i
            while not visited[j]:
                visited[j] = True
                cyc.append(j)
                j = sigma[j - 1]
            cycles.append(cyc)
    return cycles

def cycle_constants(cyc, R):
    k = len(cyc)
    m = pow(R, k) - 1
    # S1 = sum_{t=1..k} R^{k-t} (i_t - 1)
    # S2 = sum_{t=1..k} R^{k-t} (R - i_{t+1}), with i_{k+1} = i_1
    S1 = 0
    S2 = 0
    for t in range(1, k + 1):
        it = cyc[t - 1]
        ip1 = cyc[t % k]
        S1 += pow(R, k - t) * (it - 1)
        S2 += pow(R, k - t) * (R - ip1)
    return S1, S2, m, k

def crt_merge(a, m, r, mod):
    # Solve N ≡ a (mod m) and N ≡ r (mod mod)
    if m == 0:
        return (r % mod, mod)
    d = gcd(m, mod)
    diff = (r - a) % mod
    if diff % d != 0:
        return None
    m1 = m // d
    mod1 = mod // d
    inv_m1 = modinv(m1 % mod1, mod1)
    if inv_m1 is None:
        return None
    t0 = (diff // d) * inv_m1 % mod1
    new_a = a + m * t0
    new_m = m * mod1  # lcm(m, mod)
    new_a %= new_m
    return (new_a, new_m)

